### Objective
Build a production-grade Financial Analytics & Waveform Radar in Flutter demonstrating advanced `CustomPainter` drawing: an interactive multi-segment Donut Chart with animated stroke sweeps and glow shaders, and an animated Bezier Audio Waveform with dynamic amplitude fluctuation, gradient shading, and precision repaint gating.

```dart
import 'dart:math' as math;
import 'dart:ui' as ui;
import 'package:flutter/material.dart';

void main() {
  runApp(const CustomCanvasMasterclassApp());
}

class CustomCanvasMasterclassApp extends StatelessWidget {
  const CustomCanvasMasterclassApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'CustomPainter Architecture',
      debugShowCheckedModeBanner: false,
      theme: ThemeData(
        colorSchemeSeed: Colors.teal,
        useMaterial3: true,
      ),
      home: const CanvasShowcaseScreen(),
    );
  }
}

class CanvasShowcaseScreen extends StatefulWidget {
  const CanvasShowcaseScreen({super.key});

  @override
  State<CanvasShowcaseScreen> createState() => _CanvasShowcaseScreenState();
}

class _CanvasShowcaseScreenState extends State<CanvasShowcaseScreen>
    with SingleTickerProviderStateMixin {
  late final AnimationController _waveController;
  double _allocationRatio = 0.72;

  @override
  void initState() {
    super.initState();
    _waveController = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 2400),
    )..repeat();
  }

  @override
  void dispose() {
    _waveController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final colorScheme = Theme.of(context).colorScheme;

    return Scaffold(
      appBar: AppBar(
        title: const Text('Custom Graphics & Canvas'),
        centerTitle: true,
      ),
      body: ListView(
        padding: const EdgeInsets.all(20.0),
        children:
 [
          _buildSectionHeader('1. CustomPainter: Interactive Donut Gauge'),
          const SizedBox(height: 12),
          _buildDonutCard(colorScheme),
          const SizedBox(height: 28),
          _buildSectionHeader('2. Bezier Wave & Shaders: Dynamic Frequency'),
          const SizedBox(height: 12),
          _buildWaveCard(colorScheme),
          const SizedBox(height: 28),
          _buildSectionHeader('3. ClipPath: Geometric Coupon Voucher'),
          const SizedBox(height: 12),
          _buildClippedVoucher(colorScheme),
        ],
      ),
    );
  }

  Widget _buildSectionHeader(String title) {
    return Text(
      title,
      style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 15),
    );
  }

  Widget _buildDonutCard(ColorScheme colorScheme) {
    return Card(
      elevation: 2,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(20)),
      child: Padding(
        padding: const EdgeInsets.all(24.0),
        child: Column(
          children: [
            SizedBox(
              width: 180,
              height: 180,
              child: RepaintBoundary(
                child: CustomPaint(
                  painter: DonutGaugePainter(
                    progress: _allocationRatio,
                    primaryColor: colorScheme.primary,
                    backgroundColor: colorScheme.surfaceContainerHighest,
                  ),
                  child: Center(
                    child: Column(
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        Text(
                          '${(_allocationRatio * 100).toInt()}%',
                          style: TextStyle(
                            fontSize: 32,
                            fontWeight: FontWeight.w900,
                            color: colorScheme.primary,
                          ),
                        ),
                        const Text(
                          'SECURE VAULT',
                          style: TextStyle(
                            fontSize: 10,
                            letterSpacing: 1.2,
                            fontWeight: FontWeight.bold,
                            color: Colors.black45,
                          ),
                        ),
                      ],
                    ),
                  ),
                ),
              ),
            ),
            const SizedBox(height: 20),
            Slider(
              value: _allocationRatio,
              onChanged: (val) => setState(() => _allocationRatio = val),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildWaveCard(ColorScheme colorScheme) {
    return Card(
      elevation: 2,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(20)),
      clipBehavior: Clip.antiAlias,
      child: Container(
        height: 160,
        color: const Color(0xFF0F172A),
        child: AnimatedBuilder(
          animation: _waveController,
          builder: (context, _) {
            return CustomPaint(
              size: const Size(double.infinity, 160),
              painter: HarmonicWavePainter(
                phase: _waveController.value * 2 * math.pi,
                waveColor: colorScheme.primary,
              ),
            );
          },
        ),
      ),
    );
  }

  Widget _buildClippedVoucher(ColorScheme colorScheme) {
    return ClipPath(
      clipper: PerforatedVoucherClipper(notchRadius: 14.0),
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 24.0, vertical: 20.0),
        decoration: BoxDecoration(
          gradient: LinearGradient(
            colors: [colorScheme.primary, colorScheme.primaryContainer],
            begin: Alignment.topLeft,
            end: Alignment.bottomRight,
          ),
        ),
        child: Row(
          mainAxisAlignment: MainAxisAlignment.spaceBetween,
          children: [
            Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  'VIP ENTERPRISE PASS',
                  style: TextStyle(
                    color: colorScheme.onPrimary,
                    fontSize: 15,
                    fontWeight: FontWeight.bold,
                  ),
                ),
                const SizedBox(height: 4),
                Text(
                  'Verified Hardware Key Authentication',
                  style: TextStyle(
                    color: colorScheme.onPrimary.withValues(alpha: 0.8),
                    fontSize: 12,
                  ),
                ),
              ],
            ),
            Icon(Icons.qr_code_2_rounded, size: 40, color: colorScheme.onPrimary),
          ],
        ),
      ),
    );
  }
}

class DonutGaugePainter extends CustomPainter {
  final double progress;
  final Color primaryColor;
  final Color backgroundColor;

  DonutGaugePainter({
    required this.progress,
    required this.primaryColor,
    required this.backgroundColor,
  });

  @override
  void paint(Canvas canvas, Size size) {
    final center = Offset(size.width / 2, size.height / 2);
    final radius = (size.width - 24) / 2;
    const strokeWidth = 14.0;

    // 1. Background Track
    final backgroundPaint = Paint()
      ..color = backgroundColor
      ..style = PaintingStyle.stroke
      ..strokeWidth = strokeWidth;

    canvas.drawCircle(center, radius, backgroundPaint);

    // 2. Active Progress Arc with Sweep Gradient
    final activePaint = Paint()
      ..style = PaintingStyle.stroke
      ..strokeWidth = strokeWidth
      ..strokeCap = StrokeCap.round
      ..shader = ui.Gradient.sweep(
        center,
        [primaryColor.withValues(alpha: 0.4), primaryColor],
        [0.0, 1.0],
      );

    const startAngle = -math.pi / 2;
    final sweepAngle = 2 * math.pi * progress;

    canvas.drawArc(
      Rect.fromCircle(center: center, radius: radius),
      startAngle,
      sweepAngle,
      false,
      activePaint,
    );
  }

  @override
  bool shouldRepaint(covariant DonutGaugePainter oldDelegate) {
    // Precise repaint gating
    return oldDelegate.progress != progress ||
        oldDelegate.primaryColor != primaryColor ||
        oldDelegate.backgroundColor != backgroundColor;
  }
}

class HarmonicWavePainter extends CustomPainter {
  final double phase;
  final Color waveColor;

  HarmonicWavePainter({
    required this.phase,
    required this.waveColor,
  });

  @override
  void paint(Canvas canvas, Size size) {
    final width = size.width;
    final height = size.height;
    final midY = height / 2;

    final path = Path();
    path.moveTo(0, midY);

    // Render harmonic sine wave across width
    for (double x = 0; x <= width; x += 4) {
      final relativeX = x / width;
      final y = midY +
          math.sin(relativeX * 4 * math.pi + phase) * 28 *
              math.sin(relativeX * math.pi);
      path.lineTo(x, y);
    }

    // 1. Draw glowing background stroke
    final glowPaint = Paint()
      ..color = waveColor.withValues(alpha: 0.5)
      ..style = PaintingStyle.stroke
      ..strokeWidth = 6.0
      ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 8.0);
    canvas.drawPath(path, glowPaint);

    // 2. Draw core neon stroke
    final corePaint = Paint()
      ..color = Colors.white
      ..style = PaintingStyle.stroke
      ..strokeWidth = 2.5;
    canvas.drawPath(path, corePaint);
  }

  @override
  bool shouldRepaint(covariant HarmonicWavePainter oldDelegate) {
    return oldDelegate.phase != phase || oldDelegate.waveColor != waveColor;
  }
}

class PerforatedVoucherClipper extends CustomClipper<Path> {
  final double notchRadius;

  PerforatedVoucherClipper({required this.notchRadius});

  @override
  Path getClip(Size size) {
    final path = Path();
    final w = size.width;
    final h = size.height;

    path.moveTo(0, 0);
    path.lineTo(w, 0);
    path.lineTo(w, h / 2 - notchRadius);

    // Right perforated semicircular notch
    path.arcToPoint(
      Offset(w, h / 2 + notchRadius),
      radius: Radius.circular(notchRadius),
      clockwise: false,
    );

    path.lineTo(w, h);
    path.lineTo(0, h);
    path.lineTo(0, h / 2 + notchRadius);

    // Left perforated semicircular notch
    path.arcToPoint(
      Offset(0, h / 2 - notchRadius),
      radius: Radius.circular(notchRadius),
      clockwise: false,
    );

    path.close();
    return path;
  }

  @override
  bool shouldReclip(covariant PerforatedVoucherClipper oldClipper) {
    return oldClipper.notchRadius != notchRadius;
  }
}
```

### Step-by-Step Code Walkthrough

1. **High-Performance Donut Gauge (`DonutGaugePainter`)**:
   Renders background circular tracks and dynamic sweep progress arcs using `drawArc` and `ui.Gradient.sweep`. The entire widget is wrapped in `RepaintBoundary` to cache the recorded `DisplayList` on a separate compositing layer.
2. **Harmonic Bezier Waveform (`HarmonicWavePainter`)**:
   `HarmonicWavePainter` calculates sine wave harmonic frequencies driven by `_waveController.value * 2 * math.pi`. Notice the dual-pass rendering technique: the first pass applies `MaskFilter.blur` to cast a neon ambient glow, while the second pass paints a crisp white vector line.
3. **Custom Perforated Coupon Clipper (`PerforatedVoucherClipper`)**:
   Demonstrates geometric clipping with `CustomClipper<Path>`. Semicircular notches are carved out of the left and right margins using `arcToPoint(..., clockwise: false)` without requiring external graphic assets.
